node -e '
const fs = require("fs");
const grade = JSON.parse(fs.readFileSync("grade.json","utf8"));
const fields = JSON.parse(fs.readFileSync("fields.json","utf8"));
const pointers = grade.fields.map(f => f.pointer);
const expected = fields.map(f => f.pointer);
const missing = expected.filter(p => !pointers.includes(p));
const extra = pointers.filter(p => !expected.includes(p));
const statuses = new Set(["supported","contradicted","unsupported","nonfactual"]);
const badStatus = grade.fields.filter(f => !statuses.has(f.status));
const quoteMismatch = grade.fields.filter((f,i) => f.quote !== fields[i].value);
console.log(JSON.stringify({
  fieldCount: grade.fields.length,
  expectedCount: expected.length,
  missing,
  extra,
  badStatus: badStatus.map(f => [f.pointer, f.status]),
  quoteMismatch: quoteMismatch.map(f => f.pointer),
  rating: grade.readerFacingProse.rating,
  keys: Object.keys(grade)
}, null, 2));
'

