const fields = JSON.parse(fs.readFileSync("fields.json","utf8"));
const quoteMismatch = grade.fields.filter((f,i) => f.quote !== fields[i].value).map(f => f.pointer);
const required = ["fields","missingMaterialLimitations","attributionErrors","reviewerLanguageLeakage","codeDiagramErrors","readerFacingProse","unresolvedUncertainty"];
console.log(JSON.stringify({
  ok: quoteMismatch.length === 0 && required.every(k => k in grade),
  quoteMismatch,
  proseRating: grade.readerFacingProse.rating,
  statuses: grade.fields.map(f => f.pointer + ":" + f.status)
}, null, 2));
'
